namespace ghidra.util.classfinder;




using generic.jar;
using ghidra.framework;
using ghidra.util.exception;
using ghidra.util.task;

class ClassDir {

	private File dir;
	private string modulePath = "";
	private ClassPackage classPackage;

	ClassDir(File dir, TaskMonitor monitor)
    {
		this.dir = dir;
		ResourceFile module = Application.getModuleContainingResourceFile(new ResourceFile(dir));
		if (module != null) {
			modulePath = module.getAbsolutePath();
		}
		classPackage = new ClassPackage(this, "", monitor);
	}

	void getClasses(List<ClassFileInfo> list, TaskMonitor monitor)
    {
		classPackage.getClasses(list, monitor);
	}

	File getDir() {
		return dir;
	}

	string getModulePath() {
		return modulePath;
	}

	/* @Override */
	public string toString() {
		return dir.toString();
	}
}
